zahlungsmissbrauch_zahlerhaftungsbetrag <- function(schadensbetrag=NULL,betruegerische_absicht=NULL,qualifizierte_pflichtverletzung=NULL,ausschluss_absatz_2=NULL,ausschluss_absatz_4_oder_5=NULL,einordnungsnachweis=NULL) {
 schaden <- .geld(schadensbetrag)
 for(name in c('betruegerische_absicht','qualifizierte_pflichtverletzung','ausschluss_absatz_2','ausschluss_absatz_4_oder_5')) .wahrheitswert(get(name),name)
 .text(einordnungsnachweis,'einordnungsnachweis')
 if(betruegerische_absicht) betrag <- schaden else if(ausschluss_absatz_4_oder_5) betrag <- .bruch(0) else if(qualifizierte_pflichtverletzung) betrag <- schaden else if(ausschluss_absatz_2) betrag <- .bruch(0) else betrag <- if(.vergleichen(schaden,.bruch(50))<0) schaden else .bruch(50)
 eingaben <- list(schadensbetrag=schadensbetrag,betruegerische_absicht=betruegerische_absicht,qualifizierte_pflichtverletzung=qualifizierte_pflichtverletzung,ausschluss_absatz_2=ausschluss_absatz_2,ausschluss_absatz_4_oder_5=ausschluss_absatz_4_oder_5,einordnungsnachweis=einordnungsnachweis)
 ergebnis <- .geld_ergebnis(betrag,'BGB_ZAHLUNGSMISSBRAUCH_ZAHLERHAFTUNGSBETRAG',eingaben,list(list(operation='Bei Betrug voller Schaden; sonst vorrangiger Ausschluss Absatz4/5 null; sonst qualifizierte Pflichtverletzung voller Schaden; sonst Absatz2 null; sonst h\u00f6chstens50EUR.')))
 ergebnis$hinweise <- c(ergebnis$hinweise,list("Nur \u00a7675v im qualifizierten Anwendungsbereich nicht autorisierter Zahlungsvorg\u00e4nge/Zahlungsinstrumente. Betrug und qualifizierte vors\u00e4tzliche/grob fahrl\u00e4ssige kausale Pflichtverletzung nach Absatz3 getrennt bewerten. Absatz2 betrifft unbemerkbaren Missbrauch bzw. dienstleisterseitigen Verlust; Absatz4/5 betrifft qualifiziert fehlende starke Authentifizierung oder nach Anzeige entstandene Sch\u00e4den bzw. fehlende Anzeigem\u00f6glichkeit. Ausschlussflag Absatz4/5 bezeichnet den Grundtatbestand vor Betrugsausnahme. Schaden muss derselben rechtlich einheitlichen Haftungseinheit angeh\u00f6ren;50EUR nicht automatisch je Einzelbuchung erneut aussch\u00f6pfen. Keine automatische Betrugs-/Verschuldensbeurteilung, Kontokorrektur nach \u00a7675u oder Haftung des Zahlungsempf\u00e4ngers."))
 ergebnis
}
